router = APIRouter(tags=["dashboard"])


def require_dashboard_auth(request: Request) -> None:
    if not settings.dashboard_token:
        return None
    if request.cookies.get("dashboard_session") != settings.dashboard_token:
        raise HTTPException(status_code=401, detail="Unauthorized")


@router.post("/auth/login")
async def auth_login(request: Request, password: str = Form(...)):
    if password == settings.dashboard_token:
        response = RedirectResponse(url="/", status_code=302)
        response.set_cookie(
            key="dashboard_session",
            value=settings.dashboard_token,
            httponly=True,
            samesite="lax",
        )
        return response

    from app.main import templates

    return templates.TemplateResponse(
        "auth.html",
        {"request": request, "error": "Invalid token. Please try again."},
        status_code=401,
    )


@router.get("/")
async def search_page(request: Request):
    from app.main import templates

    if settings.dashboard_token and request.cookies.get("dashboard_session") != settings.dashboard_token:
        return templates.TemplateResponse("auth.html", {"request": request})
    return templates.TemplateResponse("search.html", {"request": request})


@router.post("/dashboard")
async def search_dashboard(
    request: Request,
    q: str = Form(...),
    db: AsyncSession = Depends(get_db),
    _=Depends(require_dashboard_auth),
):
    term = q.strip()
    keyword = await get_keyword_by_term(db, term)
    if keyword is None:
        keyword = await create_keyword(db, term)
    from app.main import templates

    return templates.TemplateResponse(
        "dashboard.html",
        {
            "request": request,
            "keyword_id": str(keyword.id),
            "keyword_term": keyword.term,
        },
    )


