@router.get("/dashboard/trends")
async def trends_tab(
    request: Request,
    keyword_id: str,
    db: AsyncSession = Depends(get_db),
    _=Depends(require_dashboard_auth),
):
    from app.main import templates
    import json

    try:
        kid = uuid.UUID(keyword_id)
        raw = await get_sentiment_trends(db, time_bucket="day", keyword_id=str(kid))
        if raw:
            buckets = sorted(set(r["bucket"] for r in raw))
            labels = [b.isoformat() if hasattr(b, "isoformat") else str(b) for b in buckets]
            momentum_series = [
                next(
                    (r["count"] for r in raw if r["bucket"] == b and r["sentiment_label"] == "positive"),
                    0,
                )
                for b in buckets
            ]
            volume_series = [sum(r["count"] for r in raw if r["bucket"] == b) for b in buckets]
            engagement_series = [
                (
                    next(
                        (r["count"] for r in raw if r["bucket"] == b and r["sentiment_label"] == "negative"),
                        0,
                    )
                    - next(
                        (r["count"] for r in raw if r["bucket"] == b and r["sentiment_label"] == "positive"),
                        0,
                    )
                )
                for b in buckets
            ]
            chart_data = {
                "labels": labels,
                "momentum": momentum_series,
                "volume": volume_series,
                "engagement": [abs(e) for e in engagement_series],
            }
            has_data = True
        else:
            chart_data = {}
            has_data = False
    except ValueError:
        return HTMLResponse('<div class="p-6 text-red-500">Invalid keyword ID</div>')
    except Exception:
        chart_data = {}
        has_data = False
    return templates.TemplateResponse(
        "partials/trends.html",
        {"request": request, "trend_json": json.dumps(chart_data), "has_data": has_data},
    )


def _render_markdown(text: str) -> str:
    """Convert simple markdown to safe HTML for report display."""
    import html as html_lib

    parts = []
    for section in text.split("### "):
        if not section.strip():
            continue
        lines = section.strip().split("\n", 1)
        heading = lines[0].strip()
        body = lines[1].strip() if len(lines) > 1 else ""
        body = body.replace("**", "<strong>", 1)
        body = body.replace("**", "</strong>", 1) if "**" in body else body
        body = body.replace("\n\n", "</p><p class='mb-3'>")
        body = f"<p class='mb-3'>{body}</p>" if body else ""
        parts.append(f"<div class='mb-6'><h3 class='text-xl font-semibold text-gray-900 mb-2'>{heading}</h3>{body}</div>")
    return f"<div class='prose max-w-none'>\n" + "\n".join(parts) + "\n</div>"


