import logging
import time
from collections import deque
from dataclasses import dataclass, field

logger = logging.getLogger(__name__)


@dataclass
class ErrorRecord:
    source: str
    message: str
    timestamp: float
    keyword: str | None = None


class ErrorAggregator:
    def __init__(self, max_records: int = 1000):
        self._errors: deque[ErrorRecord] = deque(maxlen=max_records)

    def record(self, source: str, message: str, keyword: str | None = None):
        record = ErrorRecord(source=source, message=message, timestamp=time.time(), keyword=keyword)
        self._errors.append(record)
        logger.error("[%s] %s (keyword=%s)", source, message, keyword or "N/A")

    def recent(self, minutes: int = 60) -> list[ErrorRecord]:
        cutoff = time.time() - (minutes * 60)
        return [e for e in self._errors if e.timestamp >= cutoff]

    def count_recent(self, source: str | None = None, minutes: int = 60) -> int:
        recent = self.recent(minutes)
        if source:
            return sum(1 for e in recent if e.source == source)
        return len(recent)

    def summary(self) -> dict:
        by_source: dict[str, int] = {}
        for e in self._errors:
            by_source[e.source] = by_source.get(e.source, 0) + 1
        return {
            "total_errors": len(self._errors),
            "errors_last_hour": self.count_recent(minutes=60),
            "by_source": by_source,
        }


