import time
from dataclasses import dataclass, field
from typing import Any


@dataclass
class SourceHealth:
    status: str = "disconnected"
    posts_ingested: int = 0
    active_keywords: int = 0
    last_activity: float = 0.0
    errors_last_hour: int = 0


class HealthCollector:
    def __init__(self):
        self.sources: dict[str, SourceHealth] = {}
        self._start_time = time.time()

    def register_source(self, name: str):
        self.sources[name] = SourceHealth()

    def update(self, name: str, **kwargs):
        if name not in self.sources:
            self.sources[name] = SourceHealth()
        for k, v in kwargs.items():
            if k in ("status", "posts_ingested", "active_keywords", "last_activity", "errors_last_hour"):
                setattr(self.sources[name], k, v)

    def report(self) -> dict[str, Any]:
        return {
            "uptime_seconds": int(time.time() - self._start_time),
            "sources": {k: vars(v) for k, v in self.sources.items()},
            "total_posts": sum(s.posts_ingested for s in self.sources.values()),
            "active_sources": sum(1 for s in self.sources.values() if s.status == "connected"),
            "total_sources": len(self.sources),
        }

"""Language detection service using lingua-py.

Provides LanguageService class for detecting text language
before sentiment classification. Thread-safe, sub-millisecond.
"""

import logging

from lingua import Language, LanguageDetectorBuilder

from app.core.config import settings

logger = logging.getLogger(__name__)


class LanguageService:
    """
    Language detection using lingua-py.
    Thread-safe — single instance shared across all inference calls.
    """

    def __init__(self):
        langs = settings.sentiment_target_languages
        if langs:
            language_enum_list = [getattr(Language, l.upper()) for l in langs]
            self._detector = LanguageDetectorBuilder.from_languages(
                *language_enum_list
            ).with_minimum_relative_distance(0.5).build()
        else:
            self._detector = LanguageDetectorBuilder.from_all_languages(
            ).with_minimum_relative_distance(0.5).build()

    def detect(self, text: str) -> dict:
        """Returns { detected_language: str | None, language_confidence: float }."""
        try:
            confidence_values = self._detector.compute_language_confidence_values(text)
            if not confidence_values:
                return {"detected_language": None, "language_confidence": 0.0}
            top = confidence_values[0]
            return {
                "detected_language": top.language.iso_code_639_1.value,
                "language_confidence": round(top.value, 4),
            }
        except Exception:
            return {"detected_language": None, "language_confidence": 0.0}

