document.addEventListener('DOMContentLoaded', () => {
    console.log('SocialPulse dashboard loaded');
});

document.body.addEventListener('htmx:afterOnLoad', (evt) => {
    if (evt.detail.target.id === 'dashboard-content') {
        const el = document.getElementById('last-updated');
        if (el) {
            el.textContent = 'Last updated: ' + new Date().toLocaleTimeString();
        }
    }
});

document.body.addEventListener('htmx:responseError', () => {
    const existing = document.getElementById('error-toast');
    if (existing) existing.remove();

    const toast = document.createElement('div');
    toast.id = 'error-toast';
    toast.className = 'fixed top-4 right-4 z-50 bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg shadow-lg text-sm';
    toast.textContent = 'Error loading dashboard data. Some sections may be unavailable.';
    document.body.appendChild(toast);

    setTimeout(() => {
        toast.style.transition = 'opacity 300ms ease-out';
        toast.style.opacity = '0';
        setTimeout(() => toast.remove(), 300);
    }, 5000);
});

document.addEventListener('alpine:init', () => {
    Alpine.data('gauge', (config) => ({
        score: config.score || 0,
        dashOffset: 100,

        get healthLabel() {
            if (this.score >= 81) return 'Exceptional';
            if (this.score >= 56) return 'Strong';
            if (this.score >= 31) return 'Growing';
            return 'Weak';
        },

        get scoreColor() {
            if (this.score >= 81) return 'text-purple-600';
            if (this.score >= 56) return 'text-green-600';
            if (this.score >= 31) return 'text-amber-500';
            return 'text-red-600';
        },

        progressColor(value) {
            if (value >= 70) return 'bg-green-500';
            if (value >= 40) return 'bg-amber-500';
            return 'bg-red-500';
        },

        animate() {
            this.$nextTick(() => {
                this.dashOffset = 100 * (100 - this.score) / 100;
            });
        },
    }));

    Alpine.data('donut', (config) => ({
        pct: config.pct || 0,
        npct: config.npct || 0,
        negpct: config.negpct || 0,
        posOffset: 251.2,
        neuOffset: 251.2,
        negOffset: 251.2,

        get topLabel() {
            if (this.pct >= this.npct && this.pct >= this.negpct) return `${this.pct}% Positive`;
            if (this.npct >= this.pct && this.npct >= this.negpct) return `${this.npct}% Neutral`;
            return `${this.negpct}% Negative`;
        },

        animate() {
            this.$nextTick(() => {
                const circumference = 251.2;
                const total = this.pct + this.npct + this.negpct;
                if (total === 0) return;
                const pos = (this.pct / 100) * circumference;
                const neu = (this.npct / 100) * circumference;
                const neg = (this.negpct / 100) * circumference;
                this.posOffset = circumference - pos;
                this.neuOffset = circumference - (pos + neu);
                this.negOffset = circumference - (pos + neu + neg);
            });
        },
    }));
});

function initTrendsChart() {
    const canvas = document.getElementById('trendsChart');
    if (!canvas) return;

    const script = document.getElementById('trend-data');
    if (!script) return;

    const data = JSON.parse(script.textContent);
    if (!data || !data.labels || data.labels.length === 0) return;

    if (window.__trendsChart) {
        window.__trendsChart.destroy();
    }

    window.__trendsChart = new Chart(canvas, {
        type: 'line',
        data: {
            labels: data.labels,
            datasets: [
                {
                    label: 'Momentum',
                    data: data.momentum,
                    borderColor: '#0969da',
                    backgroundColor: 'rgba(9,105,218,0.1)',
                    tension: 0.3,
                    fill: false,
                },
                {
                    label: 'Volume',
                    data: data.volume,
                    borderColor: '#1a7f37',
                    backgroundColor: 'rgba(26,127,55,0.1)',
                    tension: 0.3,
                    fill: false,
                },
                {
                    label: 'Engagement',
                    data: data.engagement,
                    borderColor: '#d4920b',
                    backgroundColor: 'rgba(212,146,11,0.1)',
                    tension: 0.3,
                    fill: false,
                },
            ],
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            animation: { duration: 0 },
            plugins: {
                legend: { position: 'bottom' },
            },
            scales: {
                x: { grid: { display: false } },
                y: { beginAtZero: true },
            },
        },
    });
}

document.addEventListener('htmx:afterSwap', () => {
    initTrendsChart();
});

document.addEventListener('htmx:beforeSwap', () => {
    if (window.__trendsChart) {
        window.__trendsChart.destroy();
        window.__trendsChart = null;
    }
});
